public int removeDuplicates(int[] nums) {
    List<Integer> unique = new ArrayList<>();
    for (int i = 0; i < nums.length; i++) {
        if (i == 0 || nums[i] != nums[i - 1]) {
            unique.add(nums[i]);
        }
    }
    for (int i = 0; i < unique.size(); i++) {
        nums[i] = unique.get(i);
    }
    return unique.size();
}

