def removeDuplicates(self, nums: list[int]) -> int:
    unique = []
    for i in range(len(nums)):
        if i == 0 or nums[i] != nums[i - 1]:
            unique.append(nums[i])
    nums[:len(unique)] = unique
    return len(unique)

